-- ----------------------------
-- Table structure for oa_announcement
-- ----------------------------
DROP TABLE IF EXISTS `oa_announcement`;
CREATE TABLE `oa_announcement`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '公告编号',
  `publisher_user_id` bigint NOT NULL COMMENT '发布人用户编号',
  `type` tinyint NOT NULL COMMENT '公告类型',
  `priority` tinyint NOT NULL COMMENT '优先级',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '公告标题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '公告内容',
  `url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '公告链接',
  `top` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否置顶',
  `publish_time` datetime NOT NULL COMMENT '发布时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_publisher_user_id_top_publish_time`(`publisher_user_id` ASC, `top` ASC, `publish_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 31 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'OA 公告';

