-- ----------------------------
-- Table structure for oa_announcement_receiver
-- ----------------------------
DROP TABLE IF EXISTS `oa_announcement_receiver`;
CREATE TABLE `oa_announcement_receiver`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '公告接收编号',
  `announcement_id` bigint NOT NULL COMMENT '公告编号',
  `receiver_user_id` bigint NOT NULL COMMENT '接收人用户编号',
  `read_status` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否已读',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_receiver_user_id_read_status`(`receiver_user_id` ASC, `read_status` ASC) USING BTREE,
  INDEX `idx_announcement_id_receiver_user_id`(`announcement_id` ASC, `receiver_user_id` ASC, `deleted` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 80 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'OA 公告接收人';

-- ----------------------------
-- Records of oa_announcement_receiver
-- ----------------------------
