-- ----------------------------
-- Table structure for oa_contact_share
-- ----------------------------
DROP TABLE IF EXISTS `oa_contact_share`;
CREATE TABLE `oa_contact_share`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '共享编号',
  `contact_id` bigint NOT NULL COMMENT '联系人编号',
  `user_id` bigint NOT NULL COMMENT '共享接收人用户编号',
  `category_id` bigint NULL DEFAULT NULL COMMENT '接收人的分类编号',
  `category_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '接收人的分类名称',
  `handle_status` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否已处理',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id_handle_status`(`user_id` ASC, `handle_status` ASC) USING BTREE,
  INDEX `idx_contact_id_user_id`(`contact_id` ASC, `user_id` ASC, `deleted` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'OA 联系人共享';

-- ----------------------------
-- Records of oa_contact_share
