-- ----------------------------
-- Table structure for oa_discussion
-- ----------------------------
DROP TABLE IF EXISTS `oa_discussion`;
CREATE TABLE `oa_discussion`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '讨论编号',
  `user_id` bigint NOT NULL COMMENT '发布人用户编号',
  `type` tinyint NOT NULL COMMENT '类型',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '正文',
  `file_urls` json NULL COMMENT '附件地址列表',
  `visit_count` int NOT NULL DEFAULT 0 COMMENT '访问次数',
  `vote_multiple` bit(1) NULL DEFAULT NULL COMMENT '投票是否多选',
  `vote_start_time` datetime NULL DEFAULT NULL COMMENT '投票开始时间',
  `vote_end_time` datetime NULL DEFAULT NULL COMMENT '投票结束时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_type_create_time`(`type` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'OA 讨论';

