-- ----------------------------
-- Table structure for oa_file_node
-- ----------------------------
DROP TABLE IF EXISTS `oa_file_node`;
CREATE TABLE `oa_file_node`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `parent_id` bigint NOT NULL DEFAULT 0 COMMENT '父目录编号，根目录为 0',
  `type` tinyint NOT NULL COMMENT '节点类型',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '节点名称',
  `extension` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '扩展名',
  `category` tinyint NULL DEFAULT NULL COMMENT '文件分类：1 图片、2 文档、3 视频、4 音频、5 压缩包、6 其他；文件夹为空',
  `size` bigint NOT NULL DEFAULT 0 COMMENT '文件大小，单位字节',
  `url` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '文件访问地址',
  `dept_id` bigint NULL DEFAULT NULL COMMENT '所属部门编号',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '节点状态：0 正常、1 回收站',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_parent_id`(`tenant_id` ASC, `parent_id` ASC) USING BTREE,
  INDEX `idx_creator`(`tenant_id` ASC, `creator` ASC) USING BTREE,
  INDEX `idx_creator_status_category`(`tenant_id` ASC, `creator` ASC, `status` ASC, `category` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 161 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '云盘文件节点';

