-- ----------------------------
-- Table structure for oa_note
-- ----------------------------
DROP TABLE IF EXISTS `oa_note`;
CREATE TABLE `oa_note`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '笔记编号',
  `creator_user_id` bigint NULL DEFAULT NULL COMMENT '历史创建人编号，当前使用 creator',
  `category_id` bigint NULL DEFAULT NULL COMMENT '目录编号',
  `type` tinyint NOT NULL COMMENT '笔记类型',
  `priority` tinyint NOT NULL COMMENT '优先级',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '内容',
  `favorite` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否收藏',
  `collected` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否收藏',
  `file_urls` json NULL COMMENT '附件地址列表',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_creator_user_id_category_id`(`creator_user_id` ASC, `category_id` ASC) USING BTREE,
