INSERT INTO `oa_official_doc_send` (`id`, `no`, `template_id`, `title`, `no_prefix`, `year`, `sequence`, `document_no`, `secrecy_level`, `urgency_level`, `disclosure_type`, `issue_time`, `send_dept_id`, `main_dept_ids`, `copy_dept_ids`, `signer_user_id`, `content`, `file_urls`, `formal_file_url`, `remark`, `status`, `process_instance_id`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`) VALUES (1, 'FW20260913000001', 1, '公文自动化验证-1789308070269', '测试', 2026, 1, '测试〔2026〕1号', 0, 0, 0, '1970-01-01 08:00:00', 103, '[103]', '[104]', NULL, NULL, '[]', NULL, NULL, -1, NULL, '1', '2026-09-13 22:01:11', '1', '2026-09-13 22:01:12', b'1', 1), (2, 'FW20260915000001', 2, '【测试】关于开展第三季度研发成果验收的通知', '芋科发', 2026, 101, '芋科发〔2026〕101号', 0, 0, 0, '1970-01-01 08:00:00', 103, '[103]', '[]', NULL, '<h2>关于开展第三季度研发成果验收的通知</h2><p>各相关部门：</p><p>请各项目负责人梳理研发成果、演示材料及验收清单，于本月底前完成内部评审。</p><p>一、请明确负责人员，按计划推进落实。</p><p>二、执行过程中遇到问题，请及时沟通并提交书面反馈。</p><p>三、本公文为系统功能体验测试数据，不作为实际业务指令。</p>', '[]', '', '公文测试数据-20260915；演示已通过状态，用于关联收文展示，未发起真实审批。', 2, NULL, '1', '2026-09-15 10:08:46', '1', '2026-09-15 10:08:47', b'0', 1), (3, 'FW20260915000002', 3, '【测试】关于国庆节前办公安全检查的通知', '芋行通', 2026, 102, '芋行通〔2026〕102号', 1, 1, 1, '1970-01-01 08:00:00', 103, '[103]', '[]', NULL, '<h2>关于国庆节前办公安全检查的通知</h2><p>各相关部门：</p><p>请检查办公用电、门禁和设备运行情况，形成问题清单并明确整改责任人。</p><p>一、请明确负责人员，按计划推进落实。</p><p>二、执行过程中遇到问题，请及时沟通并提交书面反馈。</p><p>三、本公文为系统功能体验测试数据，不作为实际业务指令。</p>', '[]', '', '公文测试数据-20260915；演示已通过状态，用于关联收文展示，未发起真实审批。', 2, NULL, '1', '2026-09-15 10:08:46', '1', '2026-09-15 10:08:47', b'0', 1), (4, 'FW20260915000003', 4, '【测试】关于研发项目负责人调整的通知', '芋人任', 2026, 103, '芋人任〔2026〕103号', 0, 2, 2, '1970-01-01 08:00:00', 103, '[103]', '[]', NULL, '<h2>关于研发项目负责人调整的通知</h2><p>各相关部门：</p><p>为明确项目协作责任，请各小组按最新职责分工开展工作，并做好任务交接。</p><p>一、请明确负责人员，按计划推进落实。</p><p>二、执行过程中遇到问题，请及时沟通并提交书面反馈。</p><p>三、本公文为系统功能体验测试数据，不作为实际业务指令。</p>', '[]', '', '公文测试数据-20260915；演示已通过状态，用于关联收文展示，未发起真实审批。', 2, NULL, '1', '2026-09-15 10:08:46', '1', '2026-09-15 10:08:47', b'0