  INDEX `idx_creator`(`tenant_id` ASC, `creator` ASC, `deleted` ASC, `create_time` ASC, `id` ASC) USING BTREE,
  INDEX `idx_process_instance`(`process_instance_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '加班申请';

