-- ----------------------------
-- Table structure for oa_reimbursement
-- ----------------------------
DROP TABLE IF EXISTS `oa_reimbursement`;
CREATE TABLE `oa_reimbursement`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '申请标题',
  `urgency` int NOT NULL COMMENT '紧急程度',
  `reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '申请原因',
  `witness_user_id` bigint NOT NULL COMMENT '证明人用户编号',
  `customer_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '相关客户名称',
  `payment_method` int NOT NULL COMMENT '报销方式',
  `invoice_count` int NOT NULL COMMENT '票据总数',
  `total_price` decimal(18, 2) NOT NULL COMMENT '报销总金额，单位元',
  `status` int NOT NULL COMMENT '审批状态',
  `process_instance_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'BPM 流程实例编号',
  `items` json NOT NULL COMMENT '报销明细',
  `file_urls` json NULL COMMENT '附件地址列表',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_tenant_creator`(`tenant_id` ASC, `creator` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_process_instance_id`(`process_instance_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'OA 费用报销申请';

-- ----------------------------
-- Records of oa_reimbursement
-- ----------------------------
BEGIN;
INSERT INTO `oa_reimbursement` (`id`, `title`, `urgency`, `reason`, `witness_user_id`, `customer_name`, `payment_method`, `invoice_count`, `total_price`, `status`, `process_instance_id`, `items`, `file_urls`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`) VALUES (1, 'OA验收-0916-followup-费用报销-approve', 1, 'OA验收-0916-followup-费用报销-approve', 104, '验收测试', 1, 1, 1.00, 2, 'f0b6bdde-b1de-11f1-9dec-ca5778fb00b9', '[{\"price\": 1, \"description\": \"仅验收，不付款\", \"expenseTime\": 1789002000000, \"expenseType\": 1, \"invoiceCount\": 1}]', '[]', '1', '2026-09-16 22:57:30', '104', '2026-09-16 22:57:35', b'0', 1), (2, 'OA验收-0916-followup-费用报销-reject', 1, 'OA验收-0916-followup-费用报销-reject', 104, '验收测试', 1, 1, 1.00, 3, 'f1083954-b1de-11f1-9dec-ca5778fb00b9', '[{\"price\": 1, \"description\": \"仅验收，不付款\", \"expenseTime\": 1789002000000, \"expenseType\": 1, \"invoiceCount\": 1}]', '[]', '1', '2026-09-16 22:57:31', '104', '2026-09-16 22:57:35', b'0', 1), (3, 'OA验收-0916-followup-费用报销-cancel', 1, 'OA验收-0916-followup-费用报销-cancel', 104, '验收测试', 1, 1, 1.00, 4, 'f135b20a-b1de-11f1-9dec-ca5778fb00b9', '[{\"price\": 1, \"description\": \"仅验收，不付款\", \"expenseTime\": 1789002000000, \"expenseType\": 1, \"invoiceCount\": 1}]', '[]', '1', '2026-09-16 22:57:31', '1', '2026-09-16 22:57:32', b'0', 1);
