-- ----------------------------
-- Table structure for oa_seal
-- ----------------------------
DROP TABLE IF EXISTS `oa_seal`;
CREATE TABLE `oa_seal`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `dept_id` bigint NOT NULL COMMENT '所属部门编号',
  `no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '印章编号',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '印章名称',
  `type` int NOT NULL COMMENT '印章类型',
  `category` int NULL DEFAULT NULL COMMENT '印章分类',
  `keeper_user_id` bigint NOT NULL COMMENT '保管人用户编号',
  `keeper_dept_id` bigint NOT NULL COMMENT '保管部门编号',
  `status` int NOT NULL DEFAULT 0 COMMENT '状态（0在库 1停用 2使用中）',
  `purchase_time` datetime NULL DEFAULT NULL COMMENT '购买时间',
  `enable_time` datetime NULL DEFAULT NULL COMMENT '启用时间',
  `disable_time` datetime NULL DEFAULT NULL COMMENT '停用时间',
  `pic_url` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '印章照片地址',
  `sort` int NOT NULL DEFAULT 0 COMMENT '显示顺序',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_no`(`tenant_id` ASC, `no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 29 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '印章';

