-- ----------------------------
-- Table structure for oa_seal_apply
-- ----------------------------
DROP TABLE IF EXISTS `oa_seal_apply`;
CREATE TABLE `oa_seal_apply`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '申请单号',
  `user_id` bigint NOT NULL COMMENT '申请人用户编号',
  `dept_id` bigint NULL DEFAULT NULL COMMENT '申请部门编号',
  `seal_id` bigint NOT NULL COMMENT '印章编号',
  `seal_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '印章编号快照',
  `seal_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '印章名称快照',
  `keeper_user_id` bigint NOT NULL COMMENT '保管人用户编号快照',
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '用印事由',
  `type` tinyint NOT NULL COMMENT '用印类型',
  `mode` tinyint NOT NULL COMMENT '用印方式',
  `document_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '文件标题',
  `document_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '文件类型',
  `document_count` int NOT NULL COMMENT '文件份数',
  `contract_price` decimal(18, 2) NULL DEFAULT NULL COMMENT '合同金额',
  `contract_party` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '合同对方',
  `expected_use_time` datetime NOT NULL COMMENT '预计用印时间',
  `actual_use_time` datetime NULL DEFAULT NULL COMMENT '实际用印时间',
  `expected_return_time` datetime NULL DEFAULT NULL COMMENT '预计归还时间',
  `actual_return_time` datetime NULL DEFAULT NULL COMMENT '实际归还时间',
  `use_status` tinyint NOT NULL DEFAULT 0 COMMENT '用印业务状态',
  `status` tinyint NOT NULL DEFAULT -1 COMMENT '审批状态，取 BPM 流程实例状态',
  `process_instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'BPM 流程实例编号',
  `urgent` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否紧急',
  `file_urls` json NULL COMMENT '附件地址列表',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  `seal_type` tinyint NULL DEFAULT NULL COMMENT '印章类型快照',
  `keeper_dept_id` bigint NULL DEFAULT NULL COMMENT '保管部门编号快照',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`tenant_id` ASC, `user_id` ASC) USING BTREE,
  INDEX `idx_seal_id`(`tenant_id` ASC, `seal_id` ASC) USING BTREE,
  INDEX `idx_no`(`tenant_id` ASC, `no` ASC) USING BTREE,
  INDEX `idx_process_instance`(`tenant_id` ASC, `process_instance_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 30 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用印申请';

-- ----------------------------
-- Records of oa_seal_apply
-- ----------------------------
