-- ----------------------------
-- Table structure for oa_task_receiver
-- ----------------------------
DROP TABLE IF EXISTS `oa_task_receiver`;
CREATE TABLE `oa_task_receiver`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '任务接收编号',
  `task_id` bigint NOT NULL COMMENT '任务编号',
  `user_id` bigint NOT NULL COMMENT '接收人用户编号',
  `status` tinyint NOT NULL COMMENT '接收人任务状态',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id_status`(`user_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_task_id_user_id`(`task_id` ASC, `user_id` ASC, `deleted` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 60 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'OA 任务接收人';

