-- ----------------------------
-- Table structure for oa_vehicle
-- ----------------------------
DROP TABLE IF EXISTS `oa_vehicle`;
CREATE TABLE `oa_vehicle`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '车牌号',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '车辆名称',
  `type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '车型，使用字典值',
  `category` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '车辆分类，使用字典值',
  `brand_model` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '品牌型号',
  `seat_count` int NOT NULL COMMENT '座位数',
  `bare_price` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '裸车价格',
  `mileage` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '当前里程',
  `compulsory_insurance_expire_time` datetime NULL DEFAULT NULL COMMENT '交强险到期时间',
  `commercial_insurance_expire_time` datetime NULL DEFAULT NULL COMMENT '商业险到期时间',
  `inspection_expire_time` datetime NULL DEFAULT NULL COMMENT '年检到期时间',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '车辆状态：0 空闲，1 停用，2 使用中',
  `sort` int NOT NULL DEFAULT 0 COMMENT '显示顺序',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  `dept_id` bigint NULL DEFAULT NULL COMMENT '所属部门编号',
  `pic_url` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '车辆照片 URL',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_no`(`tenant_id` ASC, `no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '车辆';

