-- ----------------------------
-- Table structure for oa_vehicle_apply
-- ----------------------------
DROP TABLE IF EXISTS `oa_vehicle_apply`;
CREATE TABLE `oa_vehicle_apply`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '用车申请单号',
  `vehicle_id` bigint NULL DEFAULT NULL COMMENT '车辆编号',
  `vehicle_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '车牌号快照',
  `user_id` bigint NOT NULL COMMENT '申请人用户编号',
  `dept_id` bigint NULL DEFAULT NULL COMMENT '申请部门编号',
  `start_time` datetime NULL DEFAULT NULL COMMENT '预计出车时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '预计回车时间',
  `start_location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '出车地点',
  `end_location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '预计回车地点',
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '用车事由',
  `passenger` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '随行人',
  `start_mileage` decimal(18, 2) NULL DEFAULT NULL COMMENT '出车里程快照',
  `status` tinyint NOT NULL DEFAULT -1 COMMENT '审批状态，取 BPM 流程实例状态',
  `return_status` tinyint NOT NULL DEFAULT 0 COMMENT '还车业务状态',
  `process_instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'BPM 流程实例编号',
  `file_urls` json NULL COMMENT '附件地址列表',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`tenant_id` ASC, `user_id` ASC) USING BTREE,
  INDEX `idx_vehicle_id`(`tenant_id` ASC, `vehicle_id` ASC) USING BTREE,
  INDEX `idx_no`(`tenant_id` ASC, `no` ASC) USING BTREE,
  INDEX `idx_process_instance`(`tenant_id` ASC, `process_instance_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用车申请';

-- ----------------------------
-- Records of oa_vehicle_apply
