-- ----------------------------
-- Table structure for oa_work_report
-- ----------------------------
DROP TABLE IF EXISTS `oa_work_report`;
CREATE TABLE `oa_work_report`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '汇报编号',
  `no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '汇报单号',
  `type` tinyint NOT NULL COMMENT '汇报类型',
  `status` tinyint NOT NULL COMMENT '汇报状态',
  `dept_id` bigint NULL DEFAULT NULL COMMENT '汇报人所属部门编号',
  `start_time` datetime NOT NULL COMMENT '周期开始时间',
  `end_time` datetime NOT NULL COMMENT '周期结束时间',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '汇报标题',
  `summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '工作总结',
  `plan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '工作计划补充说明',
  `problem` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '问题与协调事项',
  `work_items` json NULL COMMENT '已完成工作项',
  `plan_items` json NULL COMMENT '工作计划项',
  `file_urls` json NULL COMMENT '附件地址列表',
  `remark` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_dept_type_start_status`(`dept_id` ASC, `type` ASC, `start_time` ASC, `status` ASC) USING BTREE,
  INDEX `idx_creator_type_start`(`creator` ASC, `type` ASC, `start_time` ASC) USING BTREE,
  INDEX `idx_no`(`tenant_id` ASC, `no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'OA 工作汇报';

-- ----------------------------
-- Records of oa_work_report
